import{_ as p,r as s,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Миграции и наполнение - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Структура миграции","slug":"структура-миграции","link":"#структура-миграции","children":[]},{"level":2,"title":"Создание таблиц","slug":"создание-таблиц","link":"#создание-таблиц","children":[{"level":3,"title":"Подключение и движок хранения","slug":"подключение-и-движок-хранения","link":"#подключение-и-движок-хранения","children":[]}]},{"level":2,"title":"Переименование / Удаление таблиц","slug":"переименование-удаление-таблиц","link":"#переименование-удаление-таблиц","children":[]},{"level":2,"title":"Создание столбцов","slug":"создание-столбцов","link":"#создание-столбцов","children":[{"level":3,"title":"Доступные типы столбцов","slug":"доступные-типы-столбцов","link":"#доступные-типы-столбцов","children":[]},{"level":3,"title":"Модификаторы столбцов","slug":"модификаторы-столбцов","link":"#модификаторы-столбцов","children":[]}]},{"level":2,"title":"Изменение столбцов","slug":"изменение-столбцов","link":"#изменение-столбцов","children":[{"level":3,"title":"Переименование столбцов","slug":"переименование-столбцов","link":"#переименование-столбцов","children":[]},{"level":3,"title":"Удаление столбцов","slug":"удаление-столбцов","link":"#удаление-столбцов","children":[]}]},{"level":2,"title":"Создание индексов","slug":"создание-индексов","link":"#создание-индексов","children":[{"level":4,"title":"Доступные типы индексов","slug":"доступные-типы-индексов","link":"#доступные-типы-индексов","children":[]},{"level":3,"title":"Переименование индексов","slug":"переименование-индексов","link":"#переименование-индексов","children":[]},{"level":3,"title":"Удаление индексов","slug":"удаление-индексов","link":"#удаление-индексов","children":[]},{"level":3,"title":"Ограничения внешних ключей","slug":"ограничения-внешних-ключеи","link":"#ограничения-внешних-ключеи","children":[]}]},{"level":2,"title":"Структура наполнителя","slug":"структура-наполнителя","link":"#структура-наполнителя","children":[{"level":3,"title":"Вызов дополнительных наполнителей","slug":"вызов-дополнительных-наполнителеи","link":"#вызов-дополнительных-наполнителеи","children":[]}]}],"relativePath":"3.x/ru/extend/database/structure.md","filePath":"3.x/ru/extend/database/structure.md"}'),u={name:"3.x/ru/extend/database/structure.md"};function r(d,n,k,g,h,b){const t=s("pre-heading"),e=s("post-heading");return o(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"Миграции и наполнение",-1)),a(e),n[1]||(n[1]=i(`<p>Файлы миграций и наполнения позволяют создавать, изменять и заполнять таблицы базы данных. Они используются в первую очередь в <a href="./../system/plugins.html">файле обновлений плагина</a> и связаны с историей версий плагина. Все классы хранятся в директории <code>updates</code> плагина. Миграции должны рассказывать историю вашей базы данных, и эту историю можно воспроизводить как вперёд, так и назад для создания и удаления таблиц.</p><p>Вы можете сгенерировать файл миграции с помощью инструмента командной строки. Первый аргумент указывает автора и имя плагина. Второй аргумент указывает имя миграции.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:migration Acme.Blog CreatePostsTable
</code></pre></div><h2 id="структура-миграции"><a href="#структура-миграции" class="header-anchor">#</a> Структура миграции</h2><p>Файл миграции должен определять класс, расширяющий класс <code>October\\Rain\\Database\\Updates\\Migration</code>, и содержать два метода: <code>up</code> и <code>down</code>. Метод <code>up</code> используется для добавления новых таблиц, столбцов или индексов в базу данных, а метод <code>down</code> должен просто отменять операции, выполненные методом <code>up</code>. В обоих этих методах вы можете использовать построитель схемы для выразительного создания и изменения таблиц. Например, рассмотрим миграцию, которая создаёт таблицу <code>october_blog_posts</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Schema<span class="token punctuation">\\</span>Blueprint</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Updates<span class="token punctuation">\\</span>Migration</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token keyword">class</span> <span class="token class-name-definition class-name">extends</span> <span class="token class-name">Migration</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">up</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;october_blog_posts&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span>
        <span class="token punctuation">{</span>
            <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">increments</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token keyword type-declaration">string</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token keyword type-declaration">string</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;slug&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">text</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;excerpt&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">text</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;content&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">timestamp</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;published_at&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">boolean</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_published&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">default</span><span class="token punctuation">(</span><span class="token constant boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">timestamps</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">down</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">drop</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;october_blog_posts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="создание-таблиц"><a href="#создание-таблиц" class="header-anchor">#</a> Создание таблиц</h2><div class="custom-block aside"><p>При создании таблицы вы можете использовать любые методы столбцов построителя схемы для определения столбцов таблицы (см. ниже).</p></div><p>Для создания новой таблицы базы данных используйте метод <code>create</code> фасада <code>Schema</code>. Метод <code>create</code> принимает два аргумента. Первый — это имя таблицы, а второй — <code>Closure</code>, которая получает объект для определения новой таблицы.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">increments</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете проверить существование таблицы или столбца с помощью методов <code>hasTable</code> и <code>hasColumn</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">hasTable</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>

<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">hasColumn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="подключение-и-движок-хранения"><a href="#подключение-и-движок-хранения" class="header-anchor">#</a> Подключение и движок хранения</h3><p>Если вы хотите выполнить операцию схемы на подключении к базе данных, отличном от вашего подключения по умолчанию, используйте метод <code>connection</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">connection</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">increments</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для установки движка хранения таблицы задайте свойство <code>engine</code> в построителе схемы.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token property">engine</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;InnoDB&#39;</span><span class="token punctuation">;</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">increments</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="переименование-удаление-таблиц"><a href="#переименование-удаление-таблиц" class="header-anchor">#</a> Переименование / Удаление таблиц</h2><p>Для переименования существующей таблицы базы данных используйте метод <code>rename</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">rename</span><span class="token punctuation">(</span><span class="token variable">$from</span><span class="token punctuation">,</span> <span class="token variable">$to</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для удаления существующей таблицы вы можете использовать методы <code>drop</code> или <code>dropIfExists</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">drop</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">dropIfExists</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="создание-столбцов"><a href="#создание-столбцов" class="header-anchor">#</a> Создание столбцов</h2><p>Для обновления существующей таблицы мы используем метод <code>table</code> фасада <code>Schema</code>. Как и метод <code>create</code>, метод <code>table</code> принимает два аргумента: имя таблицы и <code>Closure</code>, которая получает объект, используемый для добавления столбцов в таблицу:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token keyword type-declaration">string</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="доступные-типы-столбцов"><a href="#доступные-типы-столбцов" class="header-anchor">#</a> Доступные типы столбцов</h3><p>Построитель схемы содержит множество типов столбцов, которые вы можете использовать при построении таблиц.</p><div class="table"><table tabindex="0"><thead><tr><th>Команда</th><th>Описание</th></tr></thead><tbody><tr><td><code>$table-&gt;bigIncrements(&#39;id&#39;);</code></td><td>Автоинкрементный ID (первичный ключ) с использованием эквивалента «UNSIGNED BIG INTEGER».</td></tr><tr><td><code>$table-&gt;bigInteger(&#39;votes&#39;);</code></td><td>Эквивалент BIGINT для базы данных.</td></tr><tr><td><code>$table-&gt;binary(&#39;data&#39;);</code></td><td>Эквивалент BLOB для базы данных.</td></tr><tr><td><code>$table-&gt;boolean(&#39;confirmed&#39;);</code></td><td>Эквивалент BOOLEAN для базы данных.</td></tr><tr><td><code>$table-&gt;char(&#39;name&#39;, 4);</code></td><td>Эквивалент CHAR с указанием длины.</td></tr><tr><td><code>$table-&gt;date(&#39;created_at&#39;);</code></td><td>Эквивалент DATE для базы данных.</td></tr><tr><td><code>$table-&gt;dateTime(&#39;created_at&#39;);</code></td><td>Эквивалент DATETIME для базы данных.</td></tr><tr><td><code>$table-&gt;decimal(&#39;amount&#39;, 5, 2);</code></td><td>Эквивалент DECIMAL с указанием точности и масштаба.</td></tr><tr><td><code>$table-&gt;double(&#39;column&#39;, 15, 8);</code></td><td>Эквивалент DOUBLE с точностью, 15 цифр всего и 8 после запятой.</td></tr><tr><td><code>$table-&gt;enum(&#39;choices&#39;, [&#39;foo&#39;, &#39;bar&#39;]);</code></td><td>Эквивалент ENUM для базы данных.</td></tr><tr><td><code>$table-&gt;float(&#39;amount&#39;);</code></td><td>Эквивалент FLOAT для базы данных.</td></tr><tr><td><code>$table-&gt;increments(&#39;id&#39;);</code></td><td>Автоинкрементный ID (первичный ключ) с использованием эквивалента «UNSIGNED INTEGER».</td></tr><tr><td><code>$table-&gt;integer(&#39;votes&#39;);</code></td><td>Эквивалент INTEGER для базы данных.</td></tr><tr><td><code>$table-&gt;json(&#39;options&#39;);</code></td><td>Эквивалент JSON для базы данных.</td></tr><tr><td><code>$table-&gt;jsonb(&#39;options&#39;);</code></td><td>Эквивалент JSONB для базы данных.</td></tr><tr><td><code>$table-&gt;longText(&#39;description&#39;);</code></td><td>Эквивалент LONGTEXT для базы данных.</td></tr><tr><td><code>$table-&gt;mediumInteger(&#39;numbers&#39;);</code></td><td>Эквивалент MEDIUMINT для базы данных.</td></tr><tr><td><code>$table-&gt;mediumText(&#39;description&#39;);</code></td><td>Эквивалент MEDIUMTEXT для базы данных.</td></tr><tr><td><code>$table-&gt;morphs(&#39;taggable&#39;);</code></td><td>Добавляет INTEGER <code>taggable_id</code> и STRING <code>taggable_type</code>.</td></tr><tr><td><code>$table-&gt;nullableTimestamps();</code></td><td>Аналогично <code>timestamps()</code>, но допускает NULL.</td></tr><tr><td><code>$table-&gt;rememberToken();</code></td><td>Добавляет <code>remember_token</code> как VARCHAR(100) NULL.</td></tr><tr><td><code>$table-&gt;smallInteger(&#39;votes&#39;);</code></td><td>Эквивалент SMALLINT для базы данных.</td></tr><tr><td><code>$table-&gt;softDeletes();</code></td><td>Добавляет столбец <code>deleted_at</code> для мягкого удаления.</td></tr><tr><td><code>$table-&gt;string(&#39;email&#39;);</code></td><td>Эквивалент столбца VARCHAR.</td></tr><tr><td><code>$table-&gt;string(&#39;name&#39;, 100);</code></td><td>Эквивалент VARCHAR с указанием длины.</td></tr><tr><td><code>$table-&gt;text(&#39;description&#39;);</code></td><td>Эквивалент TEXT для базы данных.</td></tr><tr><td><code>$table-&gt;time(&#39;sunrise&#39;);</code></td><td>Эквивалент TIME для базы данных.</td></tr><tr><td><code>$table-&gt;tinyInteger(&#39;numbers&#39;);</code></td><td>Эквивалент TINYINT для базы данных.</td></tr><tr><td><code>$table-&gt;timestamp(&#39;added_on&#39;);</code></td><td>Эквивалент TIMESTAMP для базы данных.</td></tr><tr><td><code>$table-&gt;timestamps();</code></td><td>Добавляет столбцы <code>created_at</code> и <code>updated_at</code>.</td></tr></tbody></table></div><h3 id="модификаторы-столбцов"><a href="#модификаторы-столбцов" class="header-anchor">#</a> Модификаторы столбцов</h3><p>Помимо перечисленных выше типов столбцов, существует несколько «модификаторов» столбцов, которые вы можете использовать при добавлении столбца. Например, чтобы сделать столбец «допускающим NULL», используйте метод <code>nullable</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token keyword type-declaration">string</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Ниже приведён список всех доступных модификаторов столбцов. Этот список не включает модификаторы индексов.</p><div class="table"><table tabindex="0"><thead><tr><th>Модификатор</th><th>Описание</th></tr></thead><tbody><tr><td><code>-&gt;nullable()</code></td><td>Разрешить вставку NULL-значений в столбец</td></tr><tr><td><code>-&gt;default($value)</code></td><td>Указать значение «по умолчанию» для столбца</td></tr><tr><td><code>-&gt;unsigned()</code></td><td>Установить столбцы <code>integer</code> как <code>UNSIGNED</code></td></tr><tr><td><code>-&gt;first()</code></td><td>Поместить столбец «первым» в таблице (только MySQL)</td></tr><tr><td><code>-&gt;after(&#39;column&#39;)</code></td><td>Поместить столбец «после» другого столбца (только MySQL)</td></tr><tr><td><code>-&gt;comment(&#39;my comment&#39;)</code></td><td>Добавить комментарий к столбцу (только MySQL)</td></tr></tbody></table></div><h2 id="изменение-столбцов"><a href="#изменение-столбцов" class="header-anchor">#</a> Изменение столбцов</h2><p>Метод <code>change</code> позволяет изменить существующий столбец на новый тип или модифицировать атрибуты столбца. Например, вы можете захотеть увеличить размер строкового столбца. Чтобы увидеть метод <code>change</code> в действии, увеличим размер столбца <code>name</code> с 25 до 50.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token keyword type-declaration">string</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token number">50</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">change</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Мы также можем сделать столбец допускающим NULL:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token keyword type-declaration">string</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token number">50</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">nullable</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">change</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="переименование-столбцов"><a href="#переименование-столбцов" class="header-anchor">#</a> Переименование столбцов</h3><p>Для переименования столбца используйте метод <code>renameColumn</code> построителя схемы.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">renameColumn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;from&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;to&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Переименование столбцов в таблице со столбцом типа <code>enum</code> в настоящее время не поддерживается.</p></div><h3 id="удаление-столбцов"><a href="#удаление-столбцов" class="header-anchor">#</a> Удаление столбцов</h3><p>Для удаления столбца используйте метод <code>dropColumn</code> построителя схемы.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">dropColumn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете удалить несколько столбцов из таблицы, передав массив имён столбцов в метод <code>dropColumn</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">dropColumn</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;avatar&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;location&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="создание-индексов"><a href="#создание-индексов" class="header-anchor">#</a> Создание индексов</h2><p>Построитель схемы поддерживает несколько типов индексов. Сначала рассмотрим пример, указывающий, что значения столбца должны быть уникальными. Для создания индекса мы можем просто добавить метод <code>unique</code> к определению столбца.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token keyword type-declaration">string</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">unique</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Альтернативно вы можете создать индекс после определения столбца. Например:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">unique</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы даже можете передать массив столбцов в метод индекса для создания составного индекса.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">index</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;created_at&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>В большинстве случаев следует указывать имя индекса вручную вторым аргументом, чтобы избежать автоматической генерации слишком длинного имени.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">index</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;account_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;created_at&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;account_created&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="доступные-типы-индексов"><a href="#доступные-типы-индексов" class="header-anchor">#</a> Доступные типы индексов</h4><div class="table"><table tabindex="0"><thead><tr><th>Команда</th><th>Описание</th></tr></thead><tbody><tr><td><code>$table-&gt;primary(&#39;id&#39;);</code></td><td>Добавить первичный ключ.</td></tr><tr><td><code>$table-&gt;primary([&#39;first&#39;, &#39;last&#39;]);</code></td><td>Добавить составные ключи.</td></tr><tr><td><code>$table-&gt;unique(&#39;email&#39;);</code></td><td>Добавить уникальный индекс.</td></tr><tr><td><code>$table-&gt;index(&#39;state&#39;);</code></td><td>Добавить базовый индекс.</td></tr></tbody></table></div><h3 id="переименование-индексов"><a href="#переименование-индексов" class="header-anchor">#</a> Переименование индексов</h3><p>Для переименования индекса используйте метод <code>renameIndex</code>, предоставляемый построителем схемы. Этот метод принимает текущее имя индекса в качестве первого аргумента и желаемое имя в качестве второго.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">renameIndex</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;from&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;to&#39;</span><span class="token punctuation">)</span>
</code></pre></div><h3 id="удаление-индексов"><a href="#удаление-индексов" class="header-anchor">#</a> Удаление индексов</h3><p>Для удаления индекса вы должны указать его имя. Если имя не было указано вручную, система автоматически генерирует его, просто объединяя имя таблицы, имя индексируемого столбца и тип индекса. Вот несколько примеров:</p><div class="table"><table tabindex="0"><thead><tr><th>Команда</th><th>Описание</th></tr></thead><tbody><tr><td><code>$table-&gt;dropPrimary(&#39;users_id_primary&#39;);</code></td><td>Удалить первичный ключ из таблицы «users».</td></tr><tr><td><code>$table-&gt;dropUnique(&#39;users_email_unique&#39;);</code></td><td>Удалить уникальный индекс из таблицы «users».</td></tr><tr><td><code>$table-&gt;dropIndex(&#39;geo_state_index&#39;);</code></td><td>Удалить базовый индекс из таблицы «geo».</td></tr></tbody></table></div><h3 id="ограничения-внешних-ключеи"><a href="#ограничения-внешних-ключеи" class="header-anchor">#</a> Ограничения внешних ключей</h3><p>Также поддерживается создание ограничений внешних ключей, которые используются для обеспечения ссылочной целостности на уровне базы данных. Например, определим столбец <code>user_id</code> в таблице <code>posts</code>, который ссылается на столбец <code>id</code> таблицы <code>users</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Schema</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$table</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">integer</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">unsigned</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">foreign</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user_id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">references</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Как и ранее, вы можете указать имя ограничения вручную, передав второй аргумент в метод <code>foreign</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">foreign</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user_id&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;user_foreign&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">references</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы также можете указать желаемое действие для свойств «on delete» и «on update» ограничения:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">foreign</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user_id&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">references</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">on</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">onDelete</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cascade&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для удаления внешнего ключа используйте метод <code>dropForeign</code>. Ограничения внешних ключей используют ту же конвенцию именования, что и индексы. Поэтому, если имя не указано вручную, мы объединяем имя таблицы и столбцы ограничения, а затем добавляем суффикс «_foreign»:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$table</span><span class="token operator">-&gt;</span><span class="token function">dropForeign</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;posts_user_id_foreign&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="структура-наполнителя"><a href="#структура-наполнителя" class="header-anchor">#</a> Структура наполнителя</h2><p>Как и файлы миграций, класс наполнителя по умолчанию содержит только один метод <code>run</code> и должен расширять класс <code>Seeder</code>. Метод <code>run</code> вызывается при выполнении процесса обновления. В этом методе вы можете вставлять данные в базу данных любым удобным способом. Вы можете использовать <a href="./query.html">конструктор запросов</a> для ручной вставки данных или ваши <a href="./model.html">классы моделей</a>. В примере ниже мы создадим нового пользователя с помощью модели <code>User</code> внутри метода <code>run</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Users<span class="token punctuation">\\</span>Updates</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Seeder</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Acme<span class="token punctuation">\\</span>Users<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>User</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">SeedUsersTable</span> <span class="token keyword">extends</span> <span class="token class-name">Seeder</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">run</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;user@example.tld&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;login&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;user&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;password&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;password123&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;password_confirmation&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;password123&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;first_name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Actual&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;last_name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Person&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;is_activated&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span>
        <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</span></code></pre></div><p>Альтернативно то же самое может быть достигнуто с помощью метода <code>Db::table</code> <a href="./query.html">конструктора запросов</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">run</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$user</span> <span class="token operator">=</span> <span class="token class-name static-context">Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">insert</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;email&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;user@example.tld&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;login&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;user&#39;</span><span class="token punctuation">,</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="вызов-дополнительных-наполнителеи"><a href="#вызов-дополнительных-наполнителеи" class="header-anchor">#</a> Вызов дополнительных наполнителей</h3><p>Внутри класса <code>DatabaseSeeder</code> вы можете использовать метод <code>call</code> для выполнения дополнительных классов наполнителей. Использование метода <code>call</code> позволяет разбить наполнение базы данных на несколько файлов, чтобы ни один класс наполнителя не стал слишком большим. Просто передайте имя класса наполнителя, который хотите запустить.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">run</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Users<span class="token punctuation">\\</span>Updates<span class="token punctuation">\\</span>UserTableSeeder</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Users<span class="token punctuation">\\</span>Updates<span class="token punctuation">\\</span>PostsTableSeeder</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Users<span class="token punctuation">\\</span>Updates<span class="token punctuation">\\</span>CommentsTableSeeder</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,81))])}const v=p(u,[["render",r]]);export{f as __pageData,v as default};
